// Function to find and print the cycle
void findAndPrintCycle(int u, int v, int P[], int n) {
    int pathU[MAX_SIZE]; // Array to store the path from u to root
    int pathV[MAX_SIZE]; // Array to store the path from v to root
    int cycle[MAX_SIZE]; // Array to store the cycle
    int pathUSize = 0;   // Current size of pathU
    int pathVSize = 0;   // Current size of pathV
    int cycleSize = 0;   // Current size of cycle
    int current;

    // Step 1: Find the path from u to the root
    current = u;
    while (current != P[current]) {
        pathU[pathUSize++] = current;
        current = P[current];
    }
    pathU[pathUSize++] = current; // Add the root

    // Step 2: Find the path from v to the root
    current = v;
    while (current != P[current]) {
        pathV[pathVSize++] = current;
        current = P[current];
    }
    pathV[pathVSize++] = current; // Add the root

    // Step 3: Remove the common part from the paths
    while (pathUSize > 0 && pathVSize > 0 && pathU[pathUSize - 1] == pathV[pathVSize - 1]) {
        --pathUSize;
        --pathVSize;
    }

    // Step 4: Form the cycle by concatenating pathU and reversed pathV
    for (int i = 0; i < pathUSize; ++i) {
        cycle[cycleSize++] = pathU[i];
    }
    cycle[cycleSize++] = pathU[pathUSize]; // Add the last common ancestor
    cycle[cycleSize++] = v; // Add v to complete the cycle
    for (int i = pathVSize - 1; i >= 0; --i) {
        cycle[cycleSize++] = pathV[i];
    }

    // Step 5: Print the cycle
    for (int i = 0; i < cycleSize; ++i) {
        printf("%d ", cycle[i]);
    }
    printf("\n");
}

